def parse_size(s):
    """Parse a human-readable size string into a number of bytes.

    Bare single-letter suffixes are decimal (K=1000, M=1000**2, G=1000**3);
    suffixes ending in 'ib' are binary (KiB=1024, MiB=1024**2, GiB=1024**3).
    Case-insensitive; surrounding whitespace tolerated; integer or float
    values allowed with any suffix. Raises ValueError with a clear message
    on empty or malformed input.
    """
    dec_units = {"k": 1000, "m": 1000**2, "g": 1000**3}
    bin_units = {"kib": 1024, "mib": 1024**2, "gib": 1024**3}

    original = s
    s = s.strip().lower()
    if not s:
        raise ValueError(f"cannot parse size from empty string: {original!r}")

    if s[-1] == "b" and s[:-1] in bin_units:
        factor = bin_units[s[:-1]]
        num = s[:-3]
    elif s[-2:] == "ib":
        raise ValueError(f"unknown size suffix in {original!r}")
    elif s[-1] in bin_units:
        raise ValueError(f"unknown size suffix in {original!r}")
    elif s[-1] in dec_units:
        factor = dec_units[s[-1]]
        num = s[:-1]
    else:
        factor = 1
        num = s

    try:
        value = int(num)
    except ValueError:
        try:
            value = float(num)
        except ValueError:
            raise ValueError(
                f"invalid number {num!r} in size string {original!r}"
            ) from None

    return int(value * factor)

